/** The roster screen: a filter bar, the roster table, and a summary footer. */
@Component({
  selector: 'app-heroes',
  imports: [
    RouterLink,
    NgIcon,
    HlmAvatarImports,
    HlmBadgeImports,
    HlmButtonImports,
    HlmInput,
    HlmLabel,
