import { Router } from '@angular/router';
import { HeroService } from '../domain/hero.service';
import type { Hero } from '../domain/hero.model';
import type { StatIcon } from '../ui/stat-tile/stat-tile';

/*
 * EXAMPLE DATA. The roster has no mission or threat feed, so these two figures
 * are fixed for the demo and labelled as such on the tiles.
 */
const EXAMPLE_LIVE_MISSIONS = 7;
const EXAMPLE_OPEN_THREATS = 3;

const TOP_HERO_COUNT = 4;

export interface DashboardStat {
  readonly label: string;
  readonly value: string;
  readonly detail: string;
  readonly icon: StatIcon;
}

/** Dashboard state: headline figures, the top heroes by power, and navigation to a dossier. */
@Injectable()
export class DashboardViewModel {
  private readonly heroes = inject(HeroService);
  private readonly router = inject(Router);

  readonly rosterCount = computed(() => this.heroes.heroes().length);

  private readonly activeCount = computed(
    () => this.heroes.heroes().filter((hero) => hero.status === 'Active').length,
  );

  private readonly averagePower = computed(() => {
    const roster = this.heroes.heroes();
    if (roster.length === 0) return 0;
    const total = roster.reduce((sum, hero) => sum + hero.powerIndex, 0);
    return Math.round(total / roster.length);
  });

  readonly stats = computed<readonly DashboardStat[]>(() => [
    {
      label: 'Heroes on roster',
      value: String(this.rosterCount()),
      detail: `${this.activeCount()} active`,
      icon: 'lucideUserCheck',
    },
    {
      label: 'Missions live',
      value: String(EXAMPLE_LIVE_MISSIONS),
      detail: 'Example data',
      icon: 'lucideActivity',
    },
    {
      label: 'Average power',
      value: String(this.averagePower()),
      detail: 'Power index, 0 to 100',
      icon: 'lucideZap',
    },
