  }

  /** Discard unsaved edits and return to the overview. */
  cancel(): void {
    this.model.set(toEditModel(this.hero()));
    this.activeTab.set('overview');
  }

  /** Send an Active hero on a mission. The roster keeps no mission log, so this records one more mission. */
  deploy(): void {
    const hero = this.hero();
    if (!hero || hero.status !== 'Active') return;
